targets.query:
from(bucket: "iot-hot")
  |> range(start: -365d)
  |> filter(fn: (r) => r._field == "temperature")

from(bucket: "iot-archives")
  |> range(start: -365d)
  |> filter(fn: (r) => r._field == "temperature")

from(bucket: "iot-hot")
  |> range(start: -24h)
  |> filter(fn: (r) => r["_measurement"] == "iot_sensors")
  |> filter(fn: (r) => r["_field"] == "temperature")
  |> last()
  |> map(fn: (r) => ({
      r with
      seconds_ago: float(v: uint(v: now()) - uint(v: r._time)) / 1000000000.0
  }))
  |> keep(columns: ["device_id", "seconds_ago"])
